struct Particle{float x,y,z,vx,vy,vz,mass;};
struct SourceParticle{float x,y,z,mass;};
extern "C" __global__ void nbody_step_naive(const Particle* in,Particle* out,int n,float dt){
 int i=blockIdx.x*blockDim.x+threadIdx.x; bool active=i<n;
 Particle target; if(active) target=in[i];
 extern __shared__ SourceParticle tile[];
 const float G=1.0f,soft=0.001f;
 float fx=0.0f,fy=0.0f,fz=0.0f;
 for(int base=0;base<n;base+=blockDim.x){
  int count=n-base; if(count>blockDim.x) count=blockDim.x;
  int load=base+threadIdx.x;
  if(load<n){Particle q=in[load]; tile[threadIdx.x]=SourceParticle{q.x,q.y,q.z,q.mass};}
  __syncthreads();
  if(active){
#pragma unroll 4
   for(int o=0;o<count;++o){
    int j=base+o; if(i==j) continue;
    SourceParticle q=tile[o];
    float dx=q.x-target.x,dy=q.y-target.y,dz=q.z-target.z;
    float r2=dx*dx+dy*dy+dz*dz+soft,inv=rsqrtf(r2);
    float f=(G*target.mass*q.mass)*inv*inv*inv;
    fx+=f*dx; fy+=f*dy; fz+=f*dz;
   }
  }
  __syncthreads();
 }
 if(!active) return;
 target.vx+=(fx/target.mass)*dt; target.vy+=(fy/target.mass)*dt; target.vz+=(fz/target.mass)*dt;
 target.x+=target.vx*dt; target.y+=target.vy*dt; target.z+=target.vz*dt;
 out[i]=target;
}

